import subprocess
import time
import sys

jobs = ['j004', 'j005']
timeout_per_cmd = 30  # seconds, shell will kill longer commands
max_total_time = 600  # 10 minutes
start = time.time()

while time.time() - start < max_total_time:
    statuses = {}
    all_done = True

    for job_id in jobs:
        try:
            result = subprocess.run(
                ['python', 'jobq.py', 'status', job_id],
                capture_output=True, text=True, timeout=5
            )
            output = result.stdout
            # Parse state from output
            if 'COMPLETED' in output:
                statuses[job_id] = 'COMPLETED'
            elif 'FAILED' in output:
                statuses[job_id] = 'FAILED'
            elif 'NODE_FAIL' in output:
                statuses[job_id] = 'NODE_FAIL'
            elif 'CANCELLED' in output:
                statuses[job_id] = 'CANCELLED'
            else:
                statuses[job_id] = 'RUNNING'
                all_done = False
        except Exception as e:
            print(f"Error checking {job_id}: {e}", file=sys.stderr)
            all_done = False

    print(f"[{time.time()-start:.0f}s] Status: {statuses}")

    if all_done:
        print("Both jobs done!")
        break

    time.sleep(15)

print(f"\nFinal check at {time.time()-start:.0f}s:")
for job_id in jobs:
    subprocess.run(['python', 'jobq.py', 'status', job_id])
EOF
